1	/**
2	 * Cross-project "my issues" view.
3	 *
4	 * Owner D. Unlike the per-project list this one spans the whole organization,
5	 * so the repository filter carries no `projectId` — only the org scope the
6	 * actor already implies.
7	 *
8	 * Must call (do not reimplement): can
9	 */
10	
11	import { notFound } from "next/navigation";
12	import type { Metadata } from "next";
13	import { IssueList } from "@/components/domain/issue/issue-list";
14	import { EmptyState } from "@/components/ui/empty-state";
15	import { can } from "@/lib/permissions";
16	import { PENDING_ISSUE_ID, PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
17	import { searchParamsPaginationSchema } from "@/schemas/pagination";
18	import { getIssue, listIssues } from "@/server/services/issue-service";
19	import { ISSUE_STATUSES, type IssueStatus, type IssueWithRelations } from "@/types/issue";
20	import { loadTenantContext } from "../_lib/tenant-context";
21	
22	type PageParams = { orgSlug: string };
23	
24	export const dynamic = "force-dynamic";
25	
26	export const metadata: Metadata = {
27	  title: "My issues",
28	};
29	
30	const OPEN_STATUSES: readonly IssueStatus[] = [
31	  "backlog",
32	  "todo",
33	  "in_progress",
34	  "in_review",
35	];
36	
37	export default async function Page(props: {
38	  params: Promise<PageParams>;
39	  searchParams: Promise<Record<string, string | string[] | undefined>>;
40	}) {
41	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
42	  const { orgSlug } = await props.params;
43	  const search = await props.searchParams;
44	
45	  const { org, actor } = await loadTenantContext(orgSlug);
46	
47	  const allowed = can(actor, "issue:read", {
48	    kind: "issue",
49	    orgId: org.id,
50	    projectId: PENDING_PROJECT_ID,
51	    issueId: PENDING_ISSUE_ID,
52	    authorId: actor.userId,
53	    assigneeId: actor.userId,
54	  });
55	  if (!allowed) {
56	    notFound();
57	  }
58	
59	  const pagination = searchParamsPaginationSchema.parse(search);
60	  const status = parseStatuses(search.status);
61	
62	  const page = await listIssues(actor, {
63	    orgId: org.id,
64	    assigneeId: actor.userId,
65	    status: [...status],
66	    limit: pagination.perPage,
67	    cursor: pagination.cursor ?? null,
68	  });
69	
70	  // `IssueList` wants the relations bundle; fetching them one by one is fine at
71	  // page size, and keeps the list query itself cheap.
72	  const rows: IssueWithRelations[] = await Promise.all(
73	    page.items.map((issue) => getIssue(actor, org.id, issue.id)),
74	  );
